export async function syntheticEvidenceV21(){const f=await syntheticEvidence();for(const id of [ARTISAN_EVIDENCE_CASES[1].id,ARTISAN_EVIDENCE_CASES[2].id]){const c=f.cache.find(c=>c.review_id===id)!;c.response.themes.professionalism={choice:'positive',probabilities:{absent:0,positive:1,negative:0,both:0}};c.theme_results=economicThemeResults(c.response)}const r=f.snapshot.source.reviews.find(r=>r.id.endsWith('000000000004'))!,c=f.cache.find(c=>c.review_id===r.id)!;r.analysis_text+=' Such good value.';r.original_text=r.analysis_text!;r.original_text_sha256=await negativeHash(r.original_text);r.analysis_text_sha256=await negativeHash(r.analysis_text!);const identity=await economyIdentity(r.organization_id,r.establishment_id,r.id,r.analysis_text!,'jev-1.13.0');Object.assign(c,identity,{cache_key:await economyCacheKey(identity)});c.response.themes.value={choice:'positive',probabilities:{absent:0,positive:1,negative:0,both:0}};c.theme_results=economicThemeResults(c.response);f.snapshot.source_sha256=await pilotSourceHash(f.snapshot.source);const cacheAudit=await auditPilotCache(f.snapshot.source.reviews,f.cache,f.snapshot.organization_id,f.snapshot.establishment_id),statistics=pilotStatistics(f.snapshot.source.reviews,cacheAudit,20),context=pilotNarrativeContext(f.snapshot,statistics,'vi');f.report.input_context={statistics,narrative_input:context};f.report.input_sha256=await pilotNarrativeHash(context);(f.report.result as {source_sha256:string}).source_sha256=f.snapshot.source_sha256;const v2=await buildEvidenceAudit(f.snapshot,f.report,f.cache),base={id:'v2-base-fixture',created_by:'owner',created_at:'2026-10-11',result:v2,result_sha256:await evidenceAuditHash(v2)},audit=await buildEvidenceV21(f.snapshot,f.report,f.cache,base),sha=await evidenceV21AuditHash(audit);return {...f,base,audit,sha}}
